fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    // Precondition: The length of the input vector must be non-negative.
    // Ensures: The output vector will have the same length as the input vector.
    //           The first part of the output vector will be filled according to the cyclic decoding rules.
    //           The remaining part of the output vector will be a copy of the input vector.
    // Requires: s.len() >= 0
    // Ensures: res.len() == s.len()
    //          forall(i: usize, 0 <= i < p ==> (i % 3 == 0 ==> res[i] == s[i + 2]) && 
    //                                              (i % 3 == 1 ==> res[i] == s[i - 1]))
    //          forall(i: usize, p <= i < len ==> res[i] == s[i])
    let len = s.len();
    let p = len - (len % 3);
    let mut res = vec![0; len]; // Initialize the result vector with the same length

    // Invariant: 0 <= i <= p and i < len
    // Decreases: p - i
    for i in 0..p {
        match i % 3 {
            0 => res[i] = s[i + 2], // If i mod 3 = 0, take the value from i + 2
            1 => res[i] = s[i - 1], // If i mod 3 = 1, take the value from i - 1
            _ => unreachable!(),     // This case will never happen since i < p and p is a multiple of 3
        }
    }

    // Copy the remaining elements from the input to the result
    // Invariant: p <= i < len
    // Decreases: len - i
    for i in p..len {
        res[i] = s[i];
    }

    res
}